private static MemoryStream WriteExcelFile(List<ZorgdagFacturatieStatusCsv> records, string praktijkInternNr)
{
    var stream = new MemoryStream();
    using (var package = new ExcelPackage(stream))
    {
        var workSheet = package.Workbook.Worksheets.Add("ZorgdagFacturatieStatus");

        var properties = typeof(ZorgdagFacturatieStatusCsv).GetProperties();
        for (int i = 0; i < properties.Length; i++)
        {
            var property = properties[i];
            workSheet.Cells[1, i + 1].Value = property.Name;
