        {
            var record = records[i];
            for (int j = 0; j < properties.Length; j++)
            {
                var property = properties[j];
                workSheet.Cells[i + 2, j + 1].Value = property.GetValue(record);
            }
        }

        package.Save();
        return stream;
    }
}
